import re
import secrets
import sqlite3
import string
import time
from collections import defaultdict
from contextlib import asynccontextmanager
from datetime import datetime, timezone
from threading import Lock

from fastapi import FastAPI, HTTPException, Request
from fastapi.responses import JSONResponse, RedirectResponse
from pydantic import BaseModel, field_validator

DB_PATH = "shortener.db"
CODE_LENGTH = 7
CODE_ALPHABET = string.ascii_letters + string.digits
RATE_LIMIT = 10
RATE_WINDOW = 60  # seconds

URL_REGEX = re.compile(
    r"^https?://"
    r"(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,63}"
    r"(?::\d{1,5})?"
    r"(?:[/?#][^\s]*)?$"
)


def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    conn = get_db()
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS urls (
                code TEXT PRIMARY KEY,
                original_url TEXT NOT NULL,
                clicks INTEGER NOT NULL DEFAULT 0,
                created_at TEXT NOT NULL
            )
            """
        )
        conn.commit()
    finally:
        conn.close()


@asynccontextmanager
async def lifespan(app: FastAPI):
    init_db()
    yield


app = FastAPI(title="URL Shortener", lifespan=lifespan)


# ---------------------------------------------------------------------------
# Rate limiting (sliding window, per IP, in-memory)
# ---------------------------------------------------------------------------

_rate_lock = Lock()
_request_log: dict[str, list[float]] = defaultdict(list)


@app.middleware("http")
async def rate_limiter(request: Request, call_next):
    client_ip = request.client.host if request.client else "unknown"
    now = time.monotonic()

    with _rate_lock:
        timestamps = _request_log[client_ip]
        cutoff = now - RATE_WINDOW
        _request_log[client_ip] = [t for t in timestamps if t > cutoff]

        if len(_request_log[client_ip]) >= RATE_LIMIT:
            retry_after = int(RATE_WINDOW - (now - _request_log[client_ip][0])) + 1
            return JSONResponse(
                status_code=429,
                content={"detail": "Rate limit exceeded. Try again later."},
                headers={"Retry-After": str(retry_after)},
            )

        _request_log[client_ip].append(now)

    return await call_next(request)


# ---------------------------------------------------------------------------
# Schemas
# ---------------------------------------------------------------------------

class ShortenRequest(BaseModel):
    url: str

    @field_validator("url")
    @classmethod
    def validate_url(cls, v: str) -> str:
        v = v.strip()
        if len(v) > 2048:
            raise ValueError("URL too long (max 2048 characters)")
        if not URL_REGEX.match(v):
            raise ValueError("Invalid URL. Must be a valid http:// or https:// URL.")
        return v


class ShortenResponse(BaseModel):
    code: str
    short_url: str
    original_url: str


class StatsResponse(BaseModel):
    code: str
    original_url: str
    clicks: int
    created_at: str


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def generate_code() -> str:
    return "".join(secrets.choice(CODE_ALPHABET) for _ in range(CODE_LENGTH))


def is_valid_code(code: str) -> bool:
    return bool(re.fullmatch(r"[A-Za-z0-9]{1,32}", code))


# ---------------------------------------------------------------------------
# Routes
# ---------------------------------------------------------------------------

@app.post("/shorten", response_model=ShortenResponse, status_code=201)
def shorten(payload: ShortenRequest, request: Request):
    conn = get_db()
    try:
        # Reuse existing code if URL already shortened
        row = conn.execute(
            "SELECT code FROM urls WHERE original_url = ?", (payload.url,)
        ).fetchone()
        if row:
            code = row["code"]
        else:
            for _ in range(10):
                code = generate_code()
                try:
                    conn.execute(
                        "INSERT INTO urls (code, original_url, clicks, created_at) "
                        "VALUES (?, ?, 0, ?)",
                        (code, payload.url, datetime.now(timezone.utc).isoformat()),
                    )
                    conn.commit()
                    break
                except sqlite3.IntegrityError:
                    continue
            else:
                raise HTTPException(status_code=500, detail="Could not generate code")
    finally:
        conn.close()

    base = str(request.base_url).rstrip("/")
    return ShortenResponse(
        code=code, short_url=f"{base}/{code}", original_url=payload.url
    )


@app.get("/stats/{code}", response_model=StatsResponse)
def stats(code: str):
    if not is_valid_code(code):
        raise HTTPException(status_code=400, detail="Invalid code format")

    conn = get_db()
    try:
        row = conn.execute(
            "SELECT code, original_url, clicks, created_at FROM urls WHERE code = ?",
            (code,),
        ).fetchone()
    finally:
        conn.close()

    if row is None:
        raise HTTPException(status_code=404, detail="Code not found")

    return StatsResponse(
        code=row["code"],
        original_url=row["original_url"],
        clicks=row["clicks"],
        created_at=row["created_at"],
    )


@app.get("/{code}")
def redirect(code: str):
    if not is_valid_code(code):
        raise HTTPException(status_code=400, detail="Invalid code format")

    conn = get_db()
    try:
        row = conn.execute(
            "SELECT original_url FROM urls WHERE code = ?", (code,)
        ).fetchone()
        if row is None:
            raise HTTPException(status_code=404, detail="Code not found")
        conn.execute("UPDATE urls SET clicks = clicks + 1 WHERE code = ?", (code,))
        conn.commit()
    finally:
        conn.close()

    return RedirectResponse(url=row["original_url"], status_code=307)


if __name__ == "__main__":
    import uvicorn

    uvicorn.run(app, host="0.0.0.0", port=8000)
```

