class LRUNode<K, V> {
  key: K;
  value: V;
  prev: LRUNode<K, V> | null = null;
  next: LRUNode<K, V> | null = null;

  constructor(key: K, value: V) {
    this.key = key;
    this.value = value;
  }
}

class LRUCache {
  private capacity: number;
  private map: Map<number, LRUNode<number, number>>;
  private head: LRUNode<number, number>; // sentinel: most recently used side
  private tail: LRUNode<number, number>; // sentinel: least recently used side

  constructor(capacity: number) {
    if (capacity <= 0) {
      throw new Error("Capacity must be a positive integer");
    }
    this.capacity = capacity;
    this.map = new Map();
    this.head = new LRUNode<number, number>(0, 0);
    this.tail = new LRUNode<number, number>(0, 0);
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  private remove(node: LRUNode<number, number>): void {
    const prev = node.prev!;
    const next = node.next!;
    prev.next = next;
    next.prev = prev;
    node.prev = null;
    node.next = null;
  }

  private addToFront(node: LRUNode<number, number>): void {
    node.next = this.head.next;
    node.prev = this.head;
    this.head.next!.prev = node;
    this.head.next = node;
  }

  get(key: number): number {
    const node = this.map.get(key);
    if (node === undefined) {
      return -1;
    }
    this.remove(node);
    this.addToFront(node);
    return node.value;
  }

  put(key: number, value: number): void {
    const existing = this.map.get(key);
    if (existing !== undefined) {
      existing.value = value;
      this.remove(existing);
      this.addToFront(existing);
      return;
    }

    if (this.map.size >= this.capacity) {
      const lru = this.tail.prev!;
      this.remove(lru);
      this.map.delete(lru.key);
    }

    const node = new LRUNode<number, number>(key, value);
    this.map.set(key, node);
    this.addToFront(node);
  }

  get size(): number {
    return this.map.size;
  }
}

// ---------------- Test Suite ----------------

function testBasicGetPut(): void {
  const cache = new LRUCache(2);
  cache.put(1, 100);
  cache.put(2, 200);
  console.assert(cache.get(1) === 100, "basic: get(1) should return 100");
  console.assert(cache.get(2) === 200, "basic: get(2) should return 200");
  console.assert(cache.get(3) === -1, "basic: get(3) should return -1 for missing key");
}

function testCapacityEviction(): void {
  const cache = new LRUCache(2);
  cache.put(1, 1);
  cache.put(2, 2);
  cache.put(3, 3); // evicts key 1 (least recently used)
  console.assert(cache.get(1) === -1, "eviction: key 1 should have been evicted");
  console.assert(cache.get(2) === 2, "eviction: key 2 should still exist");
  console.assert(cache.get(3) === 3, "eviction: key 3 should exist");
  console.assert(cache.size === 2, "eviction: size should remain at capacity");
}

function testAccessOrderUpdate(): void {
  const cache = new LRUCache(2);
  cache.put(1, 1);
  cache.put(2, 2);
  console.assert(cache.get(1) === 1, "access-order: get(1) should return 1");
  cache.put(3, 3); // key 2 is now LRU and should be evicted, not key 1
  console.assert(cache.get(2) === -1, "access-order: key 2 should have been evicted");
  console.assert(cache.get(1) === 1, "access-order: key 1 should survive (recently accessed)");
  console.assert(cache.get(3) === 3, "access-order: key 3 should exist");
}

function testOverwriteExistingKey(): void {
  const cache = new LRUCache(2);
  cache.put(1, 1);
  cache.put(2, 2);
  cache.put(1, 10); // overwrite, also marks key 1 as most recently used
  console.assert(cache.get(1) === 10, "overwrite: key 1 should return updated value 10");
  console.assert(cache.size === 2, "overwrite: size should not grow on overwrite");
  cache.put(3, 3); // should evict key 2, since key 1 was refreshed by put
  console.assert(cache.get(2) === -1, "overwrite: key 2 should have been evicted");
  console.assert(cache.get(1) === 10, "overwrite: key 1 should still return 10");
  console.assert(cache.get(3) === 3, "overwrite: key 3 should exist");
}

testBasicGetPut();
testCapacityEviction();
testAccessOrderUpdate();
testOverwriteExistingKey();

console.log("All LRU cache tests passed.");

export { LRUCache };
